import 'package:cloud_firestore/cloud_firestore.dart';
import '../../domain/entities/academic_class_entity.dart';
class AcademicClassModel extends AcademicClassEntity { const AcademicClassModel({required super.id,required super.name,required super.isActive,required super.createdAt,required super.updatedAt}); factory AcademicClassModel.fromEntity(AcademicClassEntity value)=>AcademicClassModel(id:value.id,name:value.name,isActive:value.isActive,createdAt:value.createdAt,updatedAt:value.updatedAt); factory AcademicClassModel.fromMap(Map<String,dynamic> map){final now=DateTime.now();return AcademicClassModel(id:map['id']??'',name:map['name']??'',isActive:map['isActive']??true,createdAt:_date(map['createdAt'])??now,updatedAt:_date(map['updatedAt'])??now);}Map<String,dynamic> toMap()=>{'id':id,'name':name,'nameKey':name.trim().toLowerCase(),'isActive':isActive,'createdAt':createdAt.toIso8601String(),'updatedAt':updatedAt.toIso8601String()};static DateTime? _date(dynamic value)=>value is Timestamp?value.toDate():value is String?DateTime.tryParse(value):value is DateTime?value:null;}
